import {measure,compare} from './analysis.mjs';
const $=id=>document.getElementById(id),video=$('video'),canvas=$('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});
let stream=null,reference=null,photo=null,torchOn=false,photoURL=null;
const say=t=>$('message').textContent=t;
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;video.style.display='none';$('torch').disabled=true;torchOn=false;$('torch').textContent='Fener';$('cameraStatus').textContent='Kamera kapalı';}
function available(){return !!(stream||photo);}
function controls(){$('reference').disabled=!available();$('sample').disabled=!available()||!reference;}
$('start').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Kamera için HTTPS ve desteklenen bir tarayıcı gerekir. Fotoğraf seçebilirsiniz.');stop();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920}},audio:false});video.srcObject=stream;await video.play();photo=null;video.style.display='block';$('placeholder').hidden=true;$('cameraStatus').textContent='Kamera açık';const cap=stream.getVideoTracks()[0].getCapabilities?.()||{};$('torch').disabled=!cap.torch;controls();say('Sıvıyı orta kareye hizalayın. Önce doğrulanmış referansı kaydedin.');}catch(e){stop();$('placeholder').hidden=false;controls();say(e.name==='NotAllowedError'?'Kamera izni verilmedi. Tarayıcı ayarlarından izin verebilir veya fotoğraf seçebilirsiniz.':e.message);}};
$('torch').onclick=async()=>{try{const next=!torchOn;await stream.getVideoTracks()[0].applyConstraints({advanced:[{torch:next}]});torchOn=next;$('torch').textContent=next?'Feneri kapat':'Fener';say('Referans ve numune için aynı fener ayarını kullanın.');}catch{say('Bu cihazda fener kontrolü kullanılamıyor.');}};
$('upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){say('Bir görüntü dosyası seçin.');return;}try{const next=await createImageBitmap(file);stop();photo?.close?.();photo=next;if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(file);$('placeholder').replaceChildren();const img=document.createElement('img');img.src=photoURL;img.alt='Seçilen numune';img.style.cssText='position:absolute;inset:0;width:100%;height:100%;object-fit:cover';$('placeholder').append(img);$('placeholder').hidden=false;$('cameraStatus').textContent='Fotoğraf seçildi';controls();say('Fotoğrafın orta karesi ölçülecek. Referans veya numune adımını seçin.');}catch{say('Görüntü okunamadı. JPEG veya PNG deneyin.');}e.target.value='';};
function capture(){const source=photo||video,w=photo?.width||video.videoWidth,h=photo?.height||video.videoHeight;if(!w||!h)throw new Error('Görüntü henüz hazır değil.');const box=document.querySelector('.camera').getBoundingClientRect(),scale=Math.max(box.width/w,box.height/h),size=180/scale;canvas.width=128;canvas.height=128;ctx.drawImage(source,(w-size)/2,(h-size)/2,size,size,0,0,128,128);return {stats:measure(ctx.getImageData(0,0,128,128).data,128,128),image:canvas.toDataURL('image/jpeg',.7)};}
function quality(s){return s.brightness<35?'Görüntü çok karanlık.':s.brightness>225?'Görüntü çok aydınlık.':s.clipped>.2?'Aşırı parlak veya karanlık alanlar var.':null;}
$('reference').onclick=()=>{try{const shot=capture(),issue=quality(shot.stats);if(issue){say(issue+' Işığı düzenleyip yeniden çekin.');return;}reference=shot.stats;$('refThumb').src=shot.image;$('refThumb').style.display='block';$('result').hidden=true;controls();say('Referans kaydedildi. Koşulları değiştirmeden numuneyi yerleştirin.');}catch(e){say(e.message);}};
$('sample').onclick=()=>{try{const shot=capture(),issue=quality(shot.stats);if(issue){say(issue+' Işığı düzenleyip yeniden çekin.');return;}const diff=compare(reference,shot.stats),result=$('result');result.hidden=false;result.replaceChildren();const title=document.createElement('h3');title.textContent=diff.brightness>25?'Çekim koşulları farklı olabilir':'Görsel karşılaştırma tamamlandı';const metrics=document.createElement('div');metrics.className='metrics';for(const [v,label]of [[diff.distance.toFixed(1),'RGB farkı · 0–442'],[diff.brightness.toFixed(1),'Parlaklık farkı · 0–255']]){const item=document.createElement('div'),b=document.createElement('b'),s=document.createElement('span');b.textContent=v;s.textContent=label;item.append(b,s);metrics.append(item);}const explanation=document.createElement('p');explanation.textContent='Değerler, orta alandaki ortalama kamera piksel değerlerinin farkıdır. Düşük fark saflık veya orijinallik kanıtı değildir; yüksek fark ışık, kap, kamera ayarı veya numuneden kaynaklanabilir. Kimyasal bileşim ve sahtelik bu ölçümle belirlenemez.';result.append(title,metrics,explanation);say('Ölçüm tamamlandı. Sonucu çekim koşullarıyla birlikte değerlendirin.');}catch(e){say(e.message);}};
$('reset').onclick=()=>{reference=null;$('refThumb').style.display='none';$('result').hidden=true;controls();say('Referans temizlendi. Yeni bir referans kaydedebilirsiniz.');};
window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();controls();}});
